  "interactiveHelp.sectionOnly": "The guide has a section about this part.",
  "interactiveHelp.noMatch": "The guide has nothing about “{name}” yet. Try its search.",
  "interactiveHelp.also": "Also in the guide",
  "interactiveHelp.search": "Search the guide",
  "interactiveHelp.open": "Open in the guide",
  "interactiveHelp.started": "Interactive Help is on: click a button, field or window to read about it. Esc leaves.",
  "interactiveHelp.ended": "Interactive Help is off",
  "shortcuts.interactiveHelp": "Turn Interactive Help on or off",
  "installHint.chromium": "Install it with the icon on the right of the address bar, or from the browser menu under “Install as app”.",
  "installHint.safariMac": "In Safari: File menu → “Add to Dock”.",
  "installHint.ios": "In Safari: Share icon → “Add to Home Screen”.",
  "installHint.firefox": "Firefox cannot install apps – Pare 3D still starts offline here in the tab.",
  "welcome.moreOfflineTitle": "Works offline",
  "welcome.moreOfflineBody": "after the first visit Pare 3D also starts without internet - install it like a normal program, your designs stay on your computer.",
  "welcome.moreAiTitle": "Build with AI",
  "welcome.moreAiBody": "through the MCP interface an AI assistant can create and edit shapes, in an editor it opens itself. That needs a copy you run yourself (npm run dev, or the Docker image); on layerling.com the AI connection is off.",
  "welcome.morePointsTitle": "Reference points",
  "welcome.moreSearchTitle": "Command search",
  "welcome.moreSimplifyTitle": "Simplify meshes",
  "welcome.moreSimplifyBody": "An imported mesh with a very large number of triangles is reduced to a fraction, with a before-and-after view and a slider - so cutting, grouping and dragging stay smooth.",
  "welcome.moreHistoryTitle": "History",
  "welcome.moreLookTitle": "Look as you like it",
  "welcome.moreLookBody": "Background and workplane, axis arrows for X, Y and Z, edge lines on every body, the sketch colours, and the contrast, the shadows and the direction of the light are yours to set in the settings - for example so dark bodies do not run into each other. On slower computers, fast mode turns everything costly off at once.",
  "welcome.moreHistoryBody": "look back at any earlier state of the project with a slider, without changing anything - export that state, start a new project from it or bring single objects back from it.",
  "welcome.moreDrawingTitle": "Drawing for the workshop",
  "welcome.moreDrawingBody": "Export → Drawing: front, top and side views at 1:1 on an ISO sheet, with overall sizes, hidden edges and a table of the round bores – as PDF or SVG, to print or to take to the lathe and mill.",
  "welcome.moreSearchBody": "Press Ctrl+K and type the name of a tool, a shape or a command to jump straight to it - in English or German, with the keyboard shortcuts shown beside each one. The bodies of your design are found by name as well.",
  "welcome.morePointsBody": "right-click a body to mark its centre, corners or edge middles with points that nothing prints and that shapes snap to - then place a hole exactly on the centre of another part.",
  "welcome.videosTitle": "Videos about Pare 3D",
  "welcome.videosHint": "Made by others, not by this project. The links open YouTube in a new tab; nothing is loaded from there until you click.",
  "welcome.help": "In the editor, the Help group holds a short guide and the list of every keyboard shortcut. In the footer, \"Bug report\" saves your design with everything needed for a report in the forum or on GitHub.",
  "welcome.guideLink": "Read the full user guide, with pictures",
  "welcome.guideUrl": "/guide/index.html",
  "guide.helpLink": "Read about this in the user guide",
  "guide.fullGuide": "Open the full user guide, with pictures",
  "guide.videos": "Videos by others:",
