  "guide.edges.offset": "Offset moves every face of a body by one distance, out or in. Grow a copy and keep it as a hole to get the clearance of a press fit, or shrink a body for a pin that has to go into a hole. Bodies that are only a triangle mesh often cannot be offset.",
  "deleteFace.title": "Delete face",
