  "export.stl.description": "3D print mesh",
  "export.stl.note": "Best for slicers and 3D printing. Geometry is exported as a triangulated mesh. In Chrome and Edge you pick the folder and name once; later STL exports of the design write into that file, unless you type another name: then you are asked again.",
