  "export.3mf.note": "For PrusaSlicer, Bambu Studio, OrcaSlicer and Cura. Every body stays a separate part with its name and colour.",
  "export.obj.description": "Universal 3D mesh",
  "export.obj.note": "A broadly compatible mesh format for modeling, rendering, and interchange. Colours are stored at the vertices, which Bambu Studio and OrcaSlicer read.",
  "export.step.description": "CAD / B-Rep",
  "export.step.note": "Keeps boxes, cylinders, spheres and cones as precise CAD geometry, along with anything whose edges were rounded or chamfered and bodies that came in as STEP. Threads, springs and gears go as their exact body too. Tapered, leaning and twisted shapes go exactly too. Imported meshes, for example, are beyond STEP — those go as STL.",
