  "waxup.setHint": "Choose one of the sets that come with Pare 3D, or load your own: front teeth (canine to canine) as OBJ or STL - a Meshmixer part, one file with the teeth as separate pieces, or one file per tooth - or an exocad tooth library (its folder as a .zip). Use only libraries you are allowed to use.",
